from pathlib import Path

cpp_path = Path(__file__).resolve().parents[1] / 'Source' / 'ModernPitchEngine.cpp'
cpp = cpp_path.read_text()

marker = 'PRIMITIVE_PERIOD_PATH_GEOMETRY_V1'
if marker not in cpp:
    anchor = '''    if (hypothesisCount <= 0)\n        return makeFreshRawDecision();\n\n    // TRANSITION_WAKES_DETECTOR_NOT_OUTPUT_V1\n'''
    if cpp.count(anchor) != 1:
        raise RuntimeError(
            f'primitive-period geometry anchor: expected one, found {cpp.count(anchor)}')

    insertion = '''    if (hypothesisCount <= 0)\n        return makeFreshRawDecision();\n\n    // PRIMITIVE_PERIOD_PATH_GEOMETRY_V1\n    // Octave-related detector paths may describe the same periodic family while\n    // disagreeing about whether the physical coordinate is F0 or F0/2.  Do not\n    // lower any validity/confidence threshold and do not invalidate the lower\n    // observation: when the upper octave has its own fresh, structurally strong\n    // direct measurement, treat that shorter/primitive period as the coordinate\n    // owner and keep the lower octave as family evidence.  The ranking lift is\n    // only the minimum needed to order the two already-valid hypotheses, so this\n    // cannot manufacture a coordinate that no path measured directly.\n    const auto hasFreshPrimitiveWitness = [&](float frequencyHz) noexcept\n    {\n        for (int candidateIndex = 0; candidateIndex < candidateCount; ++candidateIndex)\n        {\n            const auto& candidate = candidates[static_cast<std::size_t>(candidateIndex)];\n            if (!candidate.valid || candidate.ageInHops != 0\n                || !std::isfinite(candidate.frequencyHz)\n                || centsDistance(candidate.frequencyHz, frequencyHz) > 55.0f)\n            {\n                continue;\n            }\n\n            const float cleanliness = candidate.tonalCleanliness >= 0.0f\n                ? clamp01(candidate.tonalCleanliness) : 0.0f;\n            const float family = candidate.harmonicFamily >= 0.0f\n                ? clamp01(candidate.harmonicFamily) : 0.0f;\n\n            // These are the existing strong-family measurements, used here only\n            // to distinguish a direct primitive-period witness from a harmonic\n            // or noisy alternate lag. They do not grant validity by themselves.\n            if (candidate.periodicity >= 0.60f\n                && family >= 0.68f\n                && cleanliness >= 0.68f)\n            {\n                return true;\n            }\n        }\n        return false;\n    };\n\n    for (int upperIndex = 0; upperIndex < hypothesisCount; ++upperIndex)\n    {\n        auto& upper = hypotheses[static_cast<std::size_t>(upperIndex)];\n        if (!upper.valid || upper.freshSupportMask == 0\n            || upper.directSupportCount < 1\n            || !hasFreshPrimitiveWitness(upper.frequencyHz))\n        {\n            continue;\n        }\n\n        for (int lowerIndex = 0; lowerIndex < hypothesisCount; ++lowerIndex)\n        {\n            if (lowerIndex == upperIndex)\n                continue;\n\n            auto& lower = hypotheses[static_cast<std::size_t>(lowerIndex)];\n            if (!lower.valid || lower.freshSupportMask == 0\n                || lower.directSupportCount < 1\n                || !(lower.frequencyHz < upper.frequencyHz)\n                || centsDistance(2.0f * lower.frequencyHz, upper.frequencyHz) > 42.0f)\n            {\n                continue;\n            }\n\n            // Ranking only: keep both hypotheses valid. If the lower coordinate\n            // already scores less, no adjustment is needed. Otherwise lift the\n            // directly measured primitive period by a tiny deterministic margin.\n            constexpr float primitiveOrderingMargin = 0.035f;\n            upper.evidenceScore = std::max(upper.evidenceScore,\n                                           lower.evidenceScore\n                                               + primitiveOrderingMargin);\n        }\n    }\n\n    std::sort(hypotheses.begin(),\n              hypotheses.begin() + hypothesisCount,\n              [](const ConsensusHypothesis& left,\n                 const ConsensusHypothesis& right)\n              {\n                  return left.evidenceScore > right.evidenceScore;\n              });\n\n    // TRANSITION_WAKES_DETECTOR_NOT_OUTPUT_V1\n'''
    cpp = cpp.replace(anchor, insertion, 1)
    cpp_path.write_text(cpp)

print('PRIMITIVE_PERIOD_PATH_GEOMETRY_V1 materialized')
